//! Rust のコードの書き出し (仕様 §11)
//!
//! 名前空間ごとに `<namespace>.rs` を作り、record を struct、enum を enum にして `juiz_sdk::types::JuizType` を実装する。
//! 型のモデルは .avsc と同じスキーマを埋め込んで作るので、指紋は .avsc・`#[derive(JuizType)]` と一致する。
//! 名前空間の木 `juiz_idl.rs` は各ファイルを `include!` し、`a.b` の型を `a::b` に置く。
//! ほかの名前空間の型は `super::…` の相対パスで参照するので、生成したファイルは `juiz_idl.rs` から使う。

use std::collections::BTreeMap;

use juiz_types::DataType;

use crate::{GeneratedFile, IdlError};

/// 名前空間の木のファイル名
pub const MODULE_TREE_FILE: &str = "juiz_idl.rs";

const HEADER: &str =
    "// @generated by juiz-idl. 手で直さないこと (元の .jidl / .avsc を直して作り直す)\n";

/// 名前付き型 (record・enum) の Rust のコード。名前空間ごとのファイルと `juiz_idl.rs`
pub fn generate_rust(types: &[DataType]) -> Result<Vec<GeneratedFile>, IdlError> {
    let mut by_namespace: BTreeMap<String, Vec<&DataType>> = BTreeMap::new();
    for t in types.iter() {
        let namespace = match t {
            DataType::Record(r) => r.namespace.clone(),
            DataType::Enum(e) => e.namespace.clone(),
            _ => continue,
        };
        if namespace.is_empty() {
            return Err(IdlError::Generate {
                message: format!(
                    "type '{}' has no namespace; Rust code needs a namespace for the module path",
                    t.display_name()
                ),
            });
        }
        by_namespace.entry(namespace).or_default().push(t);
    }
    let mut files = Vec::new();
    for (namespace, ts) in by_namespace.iter() {
        let mut out = String::from(HEADER);
        for t in ts.iter() {
            out.push('\n');
            out.push_str(&type_code(t, namespace)?);
        }
        files.push(GeneratedFile {
            path: format!("{namespace}.rs").into(),
            contents: out,
        });
    }
    files.push(GeneratedFile {
        path: MODULE_TREE_FILE.into(),
        contents: module_tree(by_namespace.keys())?,
    });
    Ok(files)
}

#[derive(Default)]
struct Tree {
    children: BTreeMap<String, Tree>,
    file: Option<String>,
}

fn module_tree<'a>(namespaces: impl Iterator<Item = &'a String>) -> Result<String, IdlError> {
    let mut root = Tree::default();
    for ns in namespaces {
        let mut node = &mut root;
        for element in ns.split('.') {
            node = node.children.entry(element.to_owned()).or_default();
        }
        node.file = Some(format!("{ns}.rs"));
    }
    fn write(tree: &Tree, indent: usize, out: &mut String) -> Result<(), IdlError> {
        let pad = "    ".repeat(indent);
        if let Some(f) = &tree.file {
            // include! のパスはこのファイルからの相対パスになる
            out.push_str(&format!("{pad}include!(\"{f}\");\n"));
        }
        for (name, child) in tree.children.iter() {
            out.push_str(&format!(
                "{pad}#[allow(clippy::all)]\n{pad}pub mod {} {{\n",
                module_ident(name)?
            ));
            write(child, indent + 1, out)?;
            out.push_str(&format!("{pad}}}\n"));
        }
        Ok(())
    }
    let mut out = String::from(HEADER);
    out.push_str("// 使い方: include!(concat!(env!(\"OUT_DIR\"), \"/juiz_idl.rs\"));\n");
    write(&root, 0, &mut out)?;
    Ok(out)
}

const KEYWORDS: [&str; 51] = [
    "as", "break", "const", "continue", "crate", "else", "enum", "extern", "false", "fn", "for",
    "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub", "ref", "return",
    "self", "Self", "static", "struct", "super", "trait", "true", "type", "unsafe", "use", "where",
    "while", "async", "await", "dyn", "abstract", "become", "box", "do", "final", "macro",
    "override", "priv", "typeof", "unsized", "virtual", "yield", "try",
];

/// raw identifier (`r#…`) にできないキーワード
const NOT_RAW: [&str; 4] = ["crate", "self", "Self", "super"];

/// フィールド名・列挙の記号を Rust の識別子にする。キーワードは `r#…`、`self` などは末尾に `_` を付ける
fn ident(name: &str) -> String {
    if NOT_RAW.contains(&name) {
        format!("{name}_")
    } else if KEYWORDS.contains(&name) {
        format!("r#{name}")
    } else {
        name.to_owned()
    }
}

/// 型の名前・モジュールの名前。`self` などは使えないのでエラー
fn module_ident(name: &str) -> Result<String, IdlError> {
    if NOT_RAW.contains(&name) {
        return Err(IdlError::Generate {
            message: format!("'{name}' cannot be used as a Rust module or type name"),
        });
    }
    Ok(ident(name))
}

/// 名前付き型の Rust のパス (`namespace` のモジュールの中から見た相対パス)
fn named_path(t: &DataType, from_namespace: &str) -> Result<String, IdlError> {
    let (namespace, name) = match t {
        DataType::Record(r) => (&r.namespace, &r.name),
        DataType::Enum(e) => (&e.namespace, &e.name),
        _ => unreachable!(),
    };
    let name = module_ident(name)?;
    if namespace == from_namespace {
        return Ok(name);
    }
    let mut path: Vec<String> = from_namespace
        .split('.')
        .map(|_| "super".to_owned())
        .collect();
    for element in namespace.split('.') {
        path.push(module_ident(element)?);
    }
    path.push(name);
    Ok(path.join("::"))
}

fn rust_type(t: &DataType, from_namespace: &str) -> Result<String, IdlError> {
    Ok(match t {
        DataType::Null => "()".to_owned(),
        DataType::Boolean => "bool".to_owned(),
        DataType::Int => "i32".to_owned(),
        DataType::Long => "i64".to_owned(),
        DataType::Float => "f32".to_owned(),
        DataType::Double => "f64".to_owned(),
        DataType::String => "::std::string::String".to_owned(),
        DataType::Bytes => "::std::vec::Vec<u8>".to_owned(),
        DataType::Array(items) => format!("::std::vec::Vec<{}>", rust_type(items, from_namespace)?),
        DataType::Map(values) => format!(
            "::std::collections::HashMap<::std::string::String, {}>",
            rust_type(values, from_namespace)?
        ),
        DataType::Optional { inner, .. } => {
            format!(
                "::std::option::Option<{}>",
                rust_type(inner, from_namespace)?
            )
        }
        DataType::Record(_) | DataType::Enum(_) => named_path(t, from_namespace)?,
        DataType::Any => "::juiz_sdk::prelude::Value".to_owned(),
        DataType::Image => "::juiz_sdk::image::DynamicImage".to_owned(),
    })
}

fn doc_lines(doc: &Option<String>, pad: &str) -> String {
    match doc {
        Some(d) => d
            .lines()
            .map(|l| format!("{pad}///{}{l}\n", if l.is_empty() { "" } else { " " }))
            .collect(),
        None => String::new(),
    }
}

/// `r#"…"#` の `#` の数を、中身に出てこない数にする
fn raw_string(s: &str) -> String {
    let mut hashes = 1;
    while s.contains(&format!("\"{}", "#".repeat(hashes))) {
        hashes += 1;
    }
    let h = "#".repeat(hashes);
    format!("r{h}\"{s}\"{h}")
}

fn data_type_fn(t: &DataType) -> Result<String, IdlError> {
    let avro = t.to_avro().map_err(|e| IdlError::Generate {
        message: format!("{}: {e}", t.display_name()),
    })?;
    let avro = serde_json::to_string(&avro).unwrap();
    let message = format!("generated schema of {} is invalid", t.display_name());
    Ok(format!(
        "    fn data_type() -> ::juiz_sdk::types::DataType {{
        static DATA_TYPE: ::std::sync::OnceLock<::juiz_sdk::types::DataType> = ::std::sync::OnceLock::new();
        DATA_TYPE
            .get_or_init(|| {{
                ::juiz_sdk::types::DataType::from_avro_str({})
                    .expect({message:?})
            }})
            .clone()
    }}
",
        raw_string(&avro)
    ))
}

fn type_code(t: &DataType, namespace: &str) -> Result<String, IdlError> {
    let mut out = String::new();
    match t {
        DataType::Record(r) => {
            let name = module_ident(&r.name)?;
            out.push_str(&doc_lines(&r.doc, ""));
            out.push_str("#[allow(non_camel_case_types, non_snake_case)]\n");
            out.push_str("#[derive(Clone, Debug, PartialEq)]\n");
            out.push_str(&format!("pub struct {name} {{\n"));
            let mut to_values = String::new();
            let mut from_values = String::new();
            for f in r.fields.iter() {
                let fident = ident(&f.name);
                let ty = rust_type(&f.data_type, namespace)?;
                out.push_str(&doc_lines(&f.doc, "    "));
                out.push_str(&format!("    pub {fident}: {ty},\n"));
                to_values.push_str(&format!(
                    "        m.insert({:?}.to_owned(), ::juiz_sdk::types::JuizType::to_value(&self.{fident})?);\n",
                    f.name
                ));
                from_values.push_str(&format!(
                    "            {fident}: <{ty} as ::juiz_sdk::types::JuizType>::from_value(&obj[{:?}])?,\n",
                    f.name
                ));
            }
            out.push_str("}\n\n");
            out.push_str(&format!("impl ::juiz_sdk::types::JuizType for {name} {{\n"));
            out.push_str(&data_type_fn(t)?);
            out.push_str(&format!(
                "
    fn to_value(&self) -> ::juiz_sdk::prelude::JuizResult<::juiz_sdk::prelude::Value> {{
        let mut m = ::juiz_sdk::prelude::serde_json::Map::new();
{to_values}        Ok(::juiz_sdk::prelude::Value::Object(m))
    }}

    fn from_value(value: &::juiz_sdk::prelude::Value) -> ::juiz_sdk::prelude::JuizResult<Self> {{
        // 足りないフィールドを既定値で埋めてから読む (仕様 §4)
        let t = <Self as ::juiz_sdk::types::JuizType>::data_type();
        let obj = ::juiz_sdk::types::read_value(&t, value, {:?}).map_err(::juiz_sdk::types::type_error)?;
        Ok(Self {{
{from_values}        }})
    }}

    // Process の戻り値になったときネイティブ値で渡す (遅延評価 L2)
    fn abi_tag() -> ::std::option::Option<::std::string::String> {{
        ::std::option::Option::Some(::juiz_sdk::types::rust_abi_tag().to_owned())
    }}

    fn into_capsule(self) -> ::juiz_sdk::prelude::JuizResult<::juiz_sdk::prelude::Capsule> {{
        ::juiz_sdk::types::native_into_capsule(self)
    }}

    fn from_capsule_ptr(capsule: &::juiz_sdk::prelude::CapsulePtr) -> ::juiz_sdk::prelude::JuizResult<Self> {{
        ::juiz_sdk::types::native_from_capsule_ptr(capsule)
    }}

    fn extract(capsule: ::juiz_sdk::prelude::CapsulePtr) -> ::juiz_sdk::prelude::JuizResult<Self> {{
        ::juiz_sdk::types::native_extract(capsule)
    }}
}}
",
                r.name
            ));
        }
        DataType::Enum(e) => {
            let name = module_ident(&e.name)?;
            out.push_str(&doc_lines(&e.doc, ""));
            out.push_str("#[allow(non_camel_case_types)]\n");
            out.push_str("#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]\n");
            out.push_str(&format!("pub enum {name} {{\n"));
            let mut to_values = String::new();
            let mut from_values = String::new();
            for s in e.symbols.iter() {
                let v = ident(s);
                out.push_str(&format!("    {v},\n"));
                to_values.push_str(&format!("            Self::{v} => {s:?},\n"));
                from_values.push_str(&format!("            Some({s:?}) => Ok(Self::{v}),\n"));
            }
            out.push_str("}\n\n");
            if let Some(d) = &e.default {
                out.push_str(&format!(
                    "impl ::std::default::Default for {name} {{\n    fn default() -> Self {{\n        Self::{}\n    }}\n}}\n\n",
                    ident(d)
                ));
            }
            out.push_str(&format!("impl ::juiz_sdk::types::JuizType for {name} {{\n"));
            out.push_str(&data_type_fn(t)?);
            out.push_str(&format!(
                "
    fn to_value(&self) -> ::juiz_sdk::prelude::JuizResult<::juiz_sdk::prelude::Value> {{
        Ok(match self {{
{to_values}        }}
        .into())
    }}

    fn from_value(value: &::juiz_sdk::prelude::Value) -> ::juiz_sdk::prelude::JuizResult<Self> {{
        // 知らない記号は既定値になる (仕様 §4)
        let t = <Self as ::juiz_sdk::types::JuizType>::data_type();
        let v = ::juiz_sdk::types::read_value(&t, value, {:?}).map_err(::juiz_sdk::types::type_error)?;
        match v.as_str() {{
{from_values}            _ => unreachable!(),
        }}
    }}
}}
",
                e.name
            ));
        }
        _ => unreachable!(),
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keywords_become_raw_identifiers() {
        assert_eq!(ident("type"), "r#type");
        assert_eq!(ident("self"), "self_");
        assert_eq!(ident("x"), "x");
        assert!(module_ident("super").is_err());
    }

    #[test]
    fn raw_string_avoids_terminator() {
        assert_eq!(raw_string("a"), "r#\"a\"#");
        assert_eq!(raw_string("a\"#b"), "r##\"a\"#b\"##");
    }

    #[test]
    fn paths_across_namespaces() {
        let t = DataType::Record(juiz_types::RecordType::new("c.d", "T"));
        assert_eq!(named_path(&t, "a.b").unwrap(), "super::super::c::d::T");
        assert_eq!(named_path(&t, "c.d").unwrap(), "T");
    }
}
